const { Pattern, Scale, Note, Rhythm, Seq, Env } = strudel;

// Kick Drum
const kick = Pattern({
  1: [Note.C4, Note.E4, Note.G4],
  2: [Note.C4, Note.E4, Note.G4],
  4: [Note.C4, Note.E4, Note.G4]
});

// Hi-Hats
const hiHats = Pattern({
  1: [Note.C6, Note.C6, Note.C6, Note.C6],
  2: [Note.C6, Note.C6, Note.C6, Note.C6],
  4: [Note.C6, Note.C6, Note.C6, Note.C6]
});

// Bassline
const bassline = Seq(
  Note.B3, Note.B3, Note.C4, Note.C4,
  Note.D4, Note.D4, Note.E4, Note.E4,
  Note.F4, Note.F4, Note.G4, Note.G4
).repeat(4);

// Melodic Part (Stab)
const stab = Env({
  start: Note.C5, end: Note.C5,
  sustain: Note.G5, release: Note.C5
}).playEvery(8);

// Combine all parts
kick.play();
hiHats.play();
bassline.play();
stab.play();
