const beat = strudel => {
  const kick = strudel.osc('saw', { freq: 20, amp: 0.5, env: { attack: 0.01, decay: 0.1, sustain: 0.1, release: 0.2 } })
  const hiHat = strudel.osc('square', { freq: 500, amp: 0.3, env: { attack: 0.01, decay: 0.05, sustain: 0.1, release: 0.2 } })
  const bass = strudel.osc('saw', { freq: 50, amp: 0.4, env: { attack: 0.01, decay: 0.5, sustain: 0.2, release: 0.5 } })
  const lead = strudel.osc('triangle', { freq: 220, amp: 0.3, env: { attack: 0.01, decay: 0.2, sustain: 0.5, release: 0.2 } })

  strudel.play([
    [0, 0.125, 0.25, 0.375, 0.5, 0.625, 0.75, 0.875], // kick
    [0.125, 0.375, 0.625, 0.875], // hiHat
    [0.125, 0.375, 0.625, 0.875], // bass
    [0.25, 0.5, 0.75], // lead
  ], (t, i) => {
    if (i < 4) {
      return kick(t)
    } else if (i < 8) {
      return hiHat(t)
    } else if (i < 12) {
      return bass(t)
    } else {
      return lead(t)
    }
  }, { duration: 4 })
}

