import { Strudel } from 'strudel.cc'

const loop = new Strudel.Loop(4)

// Drums
const kick = new Strudel.Pulse({ period: 1, dutyCycle: 0.5, amplitude: 0.8, envelope: { attack: 0.01, decay: 0.1, sustain: 0.5, release: 0.05 } })
const hiHat = new Strudel.Pulse({ period: 0.25, dutyCycle: 0.2, amplitude: 0.5, envelope: { attack: 0.01, decay: 0.1, sustain: 0.5, release: 0.05 } })

loop.addLayer(new Strudel.Composite({
  1: [kick, hiHat],
  2: [kick, hiHat],
  3: [kick, hiHat],
  4: [kick, hiHat]
}))

// Bassline
const bass = new Strudel.Pulse({ period: 1, dutyCycle: 0.5, amplitude: 0.6, envelope: { attack: 0.01, decay: 0.1, sustain: 0.8, release: 0.05 }, waveform: Strudel.Wave.OscillatorTypes.SAW })
bass.setFilter({ type: Strudel.FilterTypes.BANDPASS, freq: 100, q: 1 })
bass.setLFO({ type: Strudel.LFOTypes.SAW, freq: 0.1, depth: 50 })
loop.addLayer(bass, 2)

// Melodic Part
const lead = new Strudel.Pulse({ period: 0.5, dutyCycle: 0.5, amplitude: 0.4, envelope: { attack: 0.01, decay: 0.1, sustain: 0.8, release: 0.05 }, waveform: Strudel.Wave.OscillatorTypes.SINE })
lead.setFilter({ type: Strudel.FilterTypes.LOWPASS, freq: 500, q: 1 })
lead.setLFO({ type: Strudel.LFOTypes.SAW, freq: 0.05, depth: 50 })
lead.setModulation({ source: bass, target: 'freq', amount: 0.5 })
loop.addLayer(lead, 1)

// Hall Reverb
loop.setEffect(new Strudel.Effect(Strudel.EffectTypes.REVERB, { size: 0.9, damping: 0.5, stereoImage: 0.5 }))

loop.start()

